    protected void createGenModelAnnotations() {
        String source = "http://www.eclipse.org/emf/2002/GenModel";
        this.addAnnotation((ENamedElement)this.implementationElementInParameterInstanceRefEClass, source, new String[]{"documentation", "Describes a reference to a particular ImplementationDataTypeElement instance in the context of a given ParameterDataPrototype.\r\nThus it refers to a particular element in the implementation description of a software data structure.\r\n\r\nUse Case:\r\nThe RTE generator publishes its generated structure of calibration parameters in its BSW module description using the \"constantMemory\" role of ParameterDataPrototypes. Each ParameterDataPrototype describes a group of single calibration parameters. In order to point to these single parameters, this \"instance ref\" is needed.\r\n\r\nNote that this class follows the pattern of an InstanceRef but is not implemented based on the abstract classes because the ImplementationDataType isn't either, especially because ImplementationDataTypeElement isn't derived from AtpPrototype."});
        this.addAnnotation((ENamedElement)this.getImplementationElementInParameterInstanceRef_Context(), source, new String[]{"documentation", "The context for the referred element."});
        this.addAnnotation((ENamedElement)this.getImplementationElementInParameterInstanceRef_Target(), source, new String[]{"documentation", "The referred data element."});
        this.addAnnotation((ENamedElement)this.mcSupportDataEClass, source, new String[]{"documentation", "Root element for all measurement and calibration support data related to one Implementation artifact on an ECU. There shall be one such element related to the RTE implementation (if it owns MC data) and a separate one for each module or component, which owns private MC data."});
        this.addAnnotation((ENamedElement)this.getMcSupportData_EmulationSupports(), source, new String[]{"documentation", "Describes the calibration method used by the RTE. This information is not needed for A2L generation, but to setup software emulation in the ECU.\r\nThe upper multiplicity of this role has been increased to * due to resolving an atpVariation stereotype. The previous value was -1."});
        this.addAnnotation((ENamedElement)this.getMcSupportData_McParameterInstances(), source, new String[]{"documentation", "A data instance to be used for calibration.\r\nThe upper multiplicity of this role has been increased to * due to resolving an atpVariation stereotype. The previous value was -1."});
        this.addAnnotation((ENamedElement)this.getMcSupportData_McVariableInstances(), source, new String[]{"documentation", "A data instance to be used for measurement.\r\nThe upper multiplicity of this role has been increased to * due to resolving an atpVariation stereotype. The previous value was -1."});
        this.addAnnotation((ENamedElement)this.getMcSupportData_MeasurableSystemConstantValues(), source, new String[]{"documentation", "Sets of system constant values to be transferred to the MCD system, because the system constants have been specified with \r\n\"swCalibrationAccess\" = readonly."});
        this.addAnnotation((ENamedElement)this.mcSwEmulationMethodSupportEClass, source, new String[]{"documentation", "This denotes the method used by the RTE to handle the calibration data. It is published by the RTE generator and can be used e.g. to generate the corresponding emulation method in a complex device driver.\r\n\r\nAccording to the actual method given by the category attribute,  not all attributes are always needed:\r\n\r\n* double pointered method: only baseReference is mandatory\r\n* single pointered method: only referenceTable is mandatory\r\n* initRam method: only elementGroup(s) are mandatory\r\n\r\nNote: For single/double pointered method the group locations are implicitly accessed via the reference table and their location can be found from the initial values in the M1 model of the respective pointers. Therefore, the description of elementGroups is not needed in these cases.  Likewise, for double pointered method the reference table description can be accessed via the M1 model under baseReference."});
        this.addAnnotation((ENamedElement)this.getMcSwEmulationMethodSupport_ShortLabel(), source, new String[]{"documentation", "Assigns a name to this element."});
        this.addAnnotation((ENamedElement)this.getMcSwEmulationMethodSupport_Category(), source, new String[]{"documentation", "Identifies the actual method. The possible names shall correspond to the symbols of the ECU configuration parameter for the calibration method of the RTE, and can include vendor specific methods."});
        this.addAnnotation((ENamedElement)this.getMcSwEmulationMethodSupport_BaseReference(), source, new String[]{"documentation", "Refers to the base pointer in case of the double-pointered method."});
        this.addAnnotation((ENamedElement)this.getMcSwEmulationMethodSupport_ElementGroups(), source, new String[]{"documentation", "Denotes the grouping of calibration parameters in the actual RTE code. Depending on the category, this information maybe required to set up the emulation code."});
        this.addAnnotation((ENamedElement)this.getMcSwEmulationMethodSupport_ReferenceTable(), source, new String[]{"documentation", "Refers to the pointer table in case of the single-pointered method."});
        this.addAnnotation((ENamedElement)this.getMcSwEmulationMethodSupport_VariationPoint(), source, new String[]{"documentation", "This element was generated/modified due to an atpVariation stereotype."});
        this.addAnnotation((ENamedElement)this.mcParameterElementGroupEClass, source, new String[]{"documentation", "Denotes a group of calibration parameters which are handled by the RTE as one data structure."});
        this.addAnnotation((ENamedElement)this.getMcParameterElementGroup_ShortLabel(), source, new String[]{"documentation", "Assigns a name to this element."});
        this.addAnnotation((ENamedElement)this.getMcParameterElementGroup_RamLocation(), source, new String[]{"documentation", "Refers to the RAM location of this parameter group. To be used for the init-RAM method."});
        this.addAnnotation((ENamedElement)this.getMcParameterElementGroup_RomLocation(), source, new String[]{"documentation", "Refers to the ROM location of this parameter group. To be used for the init-RAM method."});
        this.addAnnotation((ENamedElement)this.mcDataInstanceEClass, source, new String[]{"documentation", "Describes the specific properties of one data instance in order to support measurement and/or calibration of this data instance.\r\n\r\nThe most important attributes are:\r\n* Its shortName is copied from the ECU Flat map and will be used as identifier and for display by the MC system.\r\n* The category is copied from the corresponding data type (ApplicationDataType if defined, otherwise ImplementationDataType) as far as applicable.\r\n* The symbol is the one used in the programming language. It will be used to find out the actual memory address by the final generation tool with the help of linker generated information.\r\n\r\nIt is assumed that in the M1 model this part and all the aggregated and referred elements (with the exception of the Flat Map) are completely generated from \"upstream\" information. This means, that even if an element like e.g. a CompuMethod is only used via reference here, it will be copied into the M1 artifact which holds the complete McSupportData for a given Implementation."});
        this.addAnnotation((ENamedElement)this.mcDataInstanceEClass.getEOperations().get(0), source, new String[]{"body", "return (<%org.artop.aal.common.datatypes.PositiveIntegerDatatype%>)arraySize.clone();"});
        this.addAnnotation((ENamedElement)this.mcDataInstanceEClass.getEOperations().get(1), source, new String[]{"body", "arraySize.setRadix(newArraySize.getRadix());\narraySize.setNoOfDigits(newArraySize.getNoOfDigits());\nsetArraySize(newArraySize.getValue());\n"});
        this.addAnnotation((ENamedElement)this.getMcDataInstance_ArraySize(), source, new String[]{"documentation", "The existence of this attribute turns the data instance into an array of data. The attribute determines the size of the array."});
        this.addAnnotation((ENamedElement)this.getMcDataInstance_FlatMapEntry(), source, new String[]{"documentation", "Reference to the corresponding entry in the ECU Flat Map. This allows to trace back to the original specification of the generated data instance. This link shall be added by the RTE generator mainly for documentation purposes.\r\n\r\nThe reference is optional because the McDataInstance may represent an array or struct in which only the subElements correspond to FlatMap entries."});
        this.addAnnotation((ENamedElement)this.getMcDataInstance_InstanceInMemory(), source, new String[]{"documentation", "Reference to the corresponding data instance in the description of calibration data structures published by the RTE generator. This is used to support emulation methods inside the ECU, it is not required for A2L generation."});
        this.addAnnotation((ENamedElement)this.getMcDataInstance_ResultingProperties(), source, new String[]{"documentation", "These are the generated properties resulting from decisions taken by the RTE  generator for the actually implemented data instance. Only those properties are relevant here, which are needed for the measurement and calibration system."});
        this.addAnnotation((ENamedElement)this.getMcDataInstance_SubElements(), source, new String[]{"documentation", "This relation indicates, that the target element is part of a \"struct\" which is given by the source element. This information will be used by the final generator to set up the correct addressing scheme.\r\nThe upper multiplicity of this role has been increased to * due to resolving an atpVariation stereotype. The previous value was -1."});
        this.addAnnotation((ENamedElement)this.getMcDataInstance_Symbol(), source, new String[]{"documentation", "This symbolic name is used to determine the memory address during final generation of the MC configuration data (e.g. \"A2L\" file). It must be the name of the variable used by the linker. This name can differ from the shortName in case of generated C data declarations.\r\n\r\nIt is an optional attribute since it may be missing in case the instance represents an element (e.g. a single array element) which has no name in the linker map."});
        this.addAnnotation((ENamedElement)this.getMcDataInstance_VariationPoint(), source, new String[]{"documentation", "This element was generated/modified due to an atpVariation stereotype."});
    }

